/**
 * Raw native module specification.
 *
 * NOTE: This is an internal API, don't use it directly. Use the `HCE` object exported from
 * the package's entry point instead, it guarantees that every C-APDU is responded to exactly once.
 */

import type {CodegenTypes, TurboModule} from 'react-native';
import {TurboModuleRegistry} from 'react-native';

export type NativeHCEEvent = {
  /**
   * Foreground session ID (generated by JS) or background session ID (generated by native code).
   */
  sessionId: string;
  /**
   * One of: 'sessionStarted', 'readerDetected', 'readerLost', 'apdu', 'sessionInvalidated'.
   */
  type: string;
  /**
   * 'apdu' only: identifier that has to be passed back to respondApdu(), otherwise 0.
   */
  apduId: number;
  /**
   * 'apdu' only: hex-encoded C-APDU, otherwise empty string.
   */
  command: string;
  /**
   * 'apdu' only: whether the device was locked when the C-APDU was received, otherwise false.
   */
  deviceLocked: boolean;
  /**
   * 'sessionInvalidated' only: the reason of invalidation, otherwise empty string.
   */
  reason: string;
};

export type NativeHCECapabilities = {
  platform: string;
  hceSupported: boolean;
  nfcEnabled: boolean;
  eligible: boolean;
  backgroundSupported: boolean;
  presentmentSupported: boolean;
};

export interface Spec extends TurboModule {
  getCapabilities(): Promise<NativeHCECapabilities>;

  beginSession(sessionId: string): Promise<void>;
  invalidateSession(sessionId: string): void;
  setSessionAlertMessage(sessionId: string, message: string): void;

  startEmulation(sessionId: string): Promise<void>;
  stopEmulation(sessionId: string, status: string): Promise<void>;
  isEmulationRunning(sessionId: string): Promise<boolean>;

  respondApdu(sessionId: string, apduId: number, rapdu: string): Promise<void>;

  acquireExclusiveNFC(): Promise<void>;
  releaseExclusiveNFC(): void;
  isExclusiveNFC(): boolean;

  setBackgroundHandlerRegistered(registered: boolean): void;
  backgroundSessionReady(sessionId: string): boolean;

  readonly onEvent: CodegenTypes.EventEmitter<NativeHCEEvent>;
}

export default TurboModuleRegistry.getEnforcing<Spec>('NativeHCEModule');
